import { defineConfig } from 'astro/config'
import starlight from '@astrojs/starlight'
import { satteri } from '@astrojs/markdown-satteri'
import { satteriCodeLinks } from './src/plugins/satteri-code-links.mjs'
// generated by scripts/gen-reference.mjs, which the predev/prebuild hooks run before astro loads
